<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/includes/config.php';require_once dirname(__DIR__).'/config/database/connection.php';require_once dirname(__DIR__).'/app/Quotes/quote_helpers.php';
if(session_status()===PHP_SESSION_NONE){session_name('gocreative_quote');session_set_cookie_params(['lifetime'=>0,'path'=>site_path('/cotizacion/'),'secure'=>!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off','httponly'=>true,'samesite'=>'Lax']);session_start();}
header('X-Robots-Tag: noindex, nofollow, noarchive',true);header('X-Content-Type-Options: nosniff');header('X-Frame-Options: DENY');header('Referrer-Policy: no-referrer');header("Content-Security-Policy: default-src 'self'; img-src 'self' data:; style-src 'self'; script-src 'none'; frame-ancestors 'none'; base-uri 'self'; form-action 'self'");header('Cache-Control: no-store,max-age=0');
$code=strtolower(trim((string)($_GET['codigo']??'')));$quote=null;$items=[];$serviceError=false;
try{$quote=quote_find_by_public_key($code);if($quote)$items=quote_items((int)$quote['id']);}catch(Throwable $exception){error_log('Error vista pública cotización: '.$exception->getMessage());$serviceError=true;}
